const VALIDAS = ['general', 'pago_info', 'flexibilidad', 'descuento', 'dispersion', 'consulta_datos', 'escalar'];

// keywords por PRIORIDAD (escalar primero por seguridad). Se evalúan sobre texto sin acentos y en minúsculas.
const REGLAS = [
  ['escalar',        /pagu[e]|comprobante|\bcep\b|no aparece|no se refleja|reembols|devoluci|hablar con|asesor|humano|\bagente\b|reclamo|cambiar (mi )?(correo|tel|numero)|iniciar sesion|no puedo entrar|bloquead/],
  ['dispersion',     /no me lleg|no recib|dispersion|mi dinero|no ha llegado|sigo esperando el credito/],
  ['descuento',      /descuento|campa|oferta|rebaja|cupon/],
  ['consulta_datos', /cuanto (llevo|he pagado|debo|pagu)|historial|calendario|mis pagos|que fecha|cuando pague|comprobantes de mis pagos/],
  ['flexibilidad',   /no puedo pagar|no voy a poder|aplaz|prorrog|mas tiempo|promesa|refinanci|reestructur|no me alcanza|opciones de pago|ayuda para pagar/],
  ['pago_info',      /clabe|como pago|donde pago|datos de pago|liquidar|adelantar|cuanto es mi pago|metodo de pago|a que cuenta/],
];

// mensajes triviales que no cambian la intención -> reusar la guardada
const TRIVIAL = /^(ok(ay)?|va|sale|listo|gracias|grax|si|no|entiendo|perfecto|de acuerdo|dale|bien|buenas|hola)\.?!?$/i;

function normaliza(s) {
  return (s || '').toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // quita acentos
    .replace(/\s+/g, ' ')
    .trim();
}

const out = [];
for (const item of items) {
  const j = item.json;
  const msgRaw = (j.mensaje ?? $('Webhook').first().json.mensaje ?? '').toString();
  const msg = normaliza(msgRaw);
  const previo = VALIDAS.includes(j.intent_previo) ? j.intent_previo : null;

  let intent = null;
  let necesita_clasificar = false;
  let motivo = '';

  // 1) keyword fuerte -> determinístico (plan A)
  for (const [etq, rx] of REGLAS) {
    if (rx.test(msg)) { intent = etq; motivo = 'keyword'; break; }
  }

  // 2) trivial / muy corto -> reusa la guardada (plan B)
  if (!intent && (TRIVIAL.test(msgRaw.trim()) || msg.length < 4)) {
    intent = previo || 'general';
    motivo = 'trivial_reuso';
  }

  // 3) sustantivo y ambiguo -> hay que clasificar con el LLM
  if (!intent) {
    necesita_clasificar = true;
    motivo = 'ambiguo_clasificar';
  }

  out.push({ json: {
    ...j,
    necesita_clasificar,
    ...(intent ? { intent } : {}),
    _gate_motivo: motivo,
  } });
}
return out;

// ============================================================
// prefiltro_ruteo  —  n8n Code node · Mode: "Run Once for All Items"
// Va ANTES del LLM orquestador:
//   When Executed → prefiltro_ruteo → If ({{ $json.necesita_llm }} == true)
//        ├ true  → LLM orquestador (AI Agent) → Switch
//        └ false → Switch   (el pre-filtro ya puso 'output' con la decisión)
//
// Solo hace fast-path de lo MECÁNICO y de alto volumen (IGNORE, IMAGE_FLOW).
// NUNCA hace fast-path de UNSAFE ni ESCALATE: eso siempre va al LLM.
// Regla de oro: ante cualquier duda o término del servicio → necesita_llm = true.
// El Switch lee $json.output (contains), así que en fast-path escribimos ahí el JSON de decisión.
// ============================================================

function normaliza(s) {
  return (s || '').toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // quita acentos
    .replace(/\s+/g, ' ')
    .trim();
}

function decisionJSON(decision, confianza, razon) {
  // string con formato idéntico al del LLM (el Switch hace contains sobre esto)
  return JSON.stringify({ decision, es_seguro: true, confianza, razon });
}

// --- señales ---
// inyección / prompt-injection: si aparece cualquiera, SIEMPRE al LLM (para que evalúe UNSAFE)
const INYECCION = /ignora|olvida|instrucciones|system prompt|tu prompt|ahora eres|actua como|pretende ser|haz de cuenta|jailbreak|\bdan\b|modo desarrollador|repite tus|muestrame tu/;

// términos del servicio: si aparecen, NUNCA ignoramos (podría ser cliente real) → al LLM
const FINDEMO = /findemo|prestamo|\bpago\b|pagar|\bcurp\b|saldo|deuda|abono|credito|cuota|clabe|aplaz|promesa|descuento|dispersion|cashback|refinanci|comprobante|cep|\$\s?\d|\d+\s?pesos/;

// autorespuestas de OTRO negocio
const AUTORESP = /gracias por (comunicarte|contactar|escribir) (con|a)|bienvenid[oa] a|en breve (te|un|una)|te atender[ea]|horario de atencion|nuestro equipo te|dejanos tu (mensaje|consulta)/;

// spam evidente (links raros, premios, cadenas, casino/cripto)
const SPAM = /o7g\.top|bit\.ly|tinyurl|\bt\.me\/|goo\.gl|\.top\/|\.xyz\/|ganaste|felicidades.*(premio|ganad)|premio.*(reclama|gratis)|scratch card|casino|apuesta|criptomoneda|bitcoin|invierte ya|loteria|sorteo|reenvia (este|a \d+)|comparte y gana|manda esto a/;

const out = [];
for (const item of items) {
  const j = item.json;
  const rawMsg = (j.message ?? j.mensaje ?? '').toString();
  const msg = normaliza(rawMsg);

  let decision = null;       // si queda null → necesita_llm
  let confianza = 0;
  let razon = '';

  // 1) SEGURIDAD: inyección → siempre al LLM (nunca fast-path)
  if (INYECCION.test(msg)) {
    decision = null; razon = 'posible inyeccion → al LLM';
  }
  // 2) IMAGE_FLOW: marcador de comprobante (lo genera tu propio upstream, es confiable)
  else if (rawMsg.includes('[Comprobante de transferencia recibido]')) {
    decision = 'IMAGE_FLOW'; confianza = 0.99; razon = 'marcador de comprobante (pre-filtro)';
  }
  // 3) imagen NO-comprobante → al LLM (flujo normal)
  else if (/imagen recibida que no es comprobante/.test(msg)) {
    decision = null; razon = 'imagen no-comprobante → al LLM';
  }
  // 4) menciona algo del servicio → NO ignorar, al LLM (podría ser cliente real)
  else if (FINDEMO.test(msg)) {
    decision = null; razon = 'menciona termino del servicio → al LLM';
  }
  // 5) IGNORE: autorespuesta de otro negocio, spam o cadena (y sin términos FinDemo)
  else if (AUTORESP.test(msg)) {
    decision = 'IGNORE'; confianza = 0.98; razon = 'autorespuesta de otro negocio (pre-filtro)';
  }
  else if (SPAM.test(msg)) {
    decision = 'IGNORE'; confianza = 0.97; razon = 'spam/cadena (pre-filtro)';
  }
  // 6) default: al LLM
  else {
    decision = null; razon = 'sin patron claro → al LLM';
  }

  const necesita_llm = decision === null;

  out.push({ json: {
    ...j,
    necesita_llm,
    ...(necesita_llm ? {} : { output: decisionJSON(decision, confianza, razon) }),
    _prefiltro: razon,
  } });
}
return out;
